      "claim": "Pentopril, a prodrug ACE inhibitor, has 60-70% bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Benazepril has an oral bioavailability of 28-37% in healthy volunteers, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Moexipril has an oral bioavailability of 22%, just above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Delapril has an absolute bioavailability of >55% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phosphinic ACE inhibitor prodrug (fosinopril-like). Multiple structurally related ACE inhibitor prodrugs have absolute oral bioavailability values well above 20%, including the closest analogue SQ 29852 (66%), perindopril (~75%), quinapril (~50%), pentopril (60-70%), benazepril (28-37%), moexipril (22%), and delapril (>55%). The consistent experimental evidence strongly supports F >= 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for fosinopril itself was provided.",
    "The low bioavailability of perindoprilat (active diacid, ~19%) is not transferable to the ester prodrug query.",
    "Morgan similarities are moderate, but the consistent ACE inhibitor prodrug class evidence mitigates this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

